/* js/data/courses_plus.js — chapitres supplémentaires (COURS) et leçons détaillées (LESSONS, plusieurs par matière) */

const les=(t,b)=>[t,b+`<p style="text-align:center"><button class="btn p" onclick="toggleLes()">Passer au quiz →</button></p>`];
LESSONS.mon=[LESSONS.mon];

/* CHAPTERS[id] : chapitres du programme ; chaque chapitre regroupe des leçons (indices dans LESSONS[id]). Voir CONTEXT.md §4 */
const CHAPTERS={};

/* ============ TES – Équipements vidéo ============ */
COURS.tes.push(
["Optique & exposition",["f/ = rapport focale/diamètre ; chaque cran (1 stop) double ou divise la lumière : f/1,4 – 2 – 2,8 – 4 – 5,6 – 8 – 11 – 16.","T-stop = transmission réelle (objectifs cinéma) ; filtre ND = moins de lumière sans changer l’ouverture.","Zébras, false colors, histogramme : outils de contrôle de l’exposition."]],
["Numérisation de l’image",["Définitions : SD 720×576, HD 1280×720, Full HD 1920×1080, UHD 3840×2160, 4K DCI 4096×2160.","Sous-échantillonnage : 4:4:4 (aucune perte de chroma), 4:2:2 (chroma /2 en horizontal), 4:2:0 (chroma /2 en horizontal et vertical).","8 bits = 256 niveaux, 10 bits = 1 024 niveaux (moins de banding)."]],
["Codecs & conteneurs",["Intra-frame (ProRes, DNxHR) : chaque image est indépendante → idéal montage.","Inter-frame / GOP (H.264, H.265, XAVC LongGOP) : images I, P, B → léger mais plus lourd à décoder.","Conteneurs : MOV, MP4, MXF (broadcast/Avid), MKV."]],
["Stockage & réseau",["Taille (Mo) = débit (Mb/s) × durée (s) ÷ 8.","RAID 0 = vitesse sans sécurité ; RAID 1 = miroir ; RAID 5 = parité (1 panne tolérée).","Règle 3-2-1 : 3 copies, 2 supports, 1 copie hors site. Toujours vérifier la copie par checksum."]],
["Audio numérique",["48 kHz / 24 bits en vidéo ; dynamique ≈ 6 dB par bit.","0 dBFS = maximum numérique : au-delà, écrêtage (clipping).","EBU R128 : −23 LUFS, crête réelle max −1 dBTP."]],
["Timecode, synchro & couleur",["Timecode HH:MM:SS:FF ; drop frame uniquement en 29,97 / 59,94 i/s.","Genlock : synchronise les sources vidéo ; LTC : timecode transporté sur une piste audio.","Rec.709 (HD), Rec.2020 (UHD/HDR), DCI-P3 (cinéma), sRGB (web). Scopes : waveform, vectorscope, parade."]]
);
LESSONS.tes=[
les("📖 1. Caméra, capteur et optique",`<h3>Le capteur</h3><p>Le capteur transforme la lumière en signal électrique. Plus il est grand, plus il capte de lumière et plus la profondeur de champ est faible à cadrage et ouverture égaux. Formats courants : Micro 4/3 (≈ 17,3 × 13 mm), Super 35 (≈ 24,9 × 18,7 mm), Full Frame (36 × 24 mm).</p><ul><li><b>Dynamique :</b> exprimée en <i>stops</i> (diaphragmes). 14 stops = rapport de luminosité de 2<sup>14</sup>.</li><li><b>ISO natif :</b> sensibilité où le bruit est minimal ; au-delà, on amplifie le signal donc le bruit.</li><li><b>Rolling shutter :</b> lecture ligne par ligne, déformation sur mouvements rapides. <b>Global shutter :</b> lecture simultanée, pas de déformation.</li><li><b>Profil Log :</b> courbe aplatie qui préserve la dynamique ; demande un étalonnage ou une LUT.</li></ul><h3>L’obturateur</h3><p>Règle des 180° : vitesse = 1 / (2 × fps). À 25 i/s : 1/50 s. En Europe, cela évite aussi le <i>flicker</i> avec les lumières alimentées en 50 Hz.</p><h3>L’objectif</h3><ul><li><b>Monture</b> (PL, EF, E, MFT…) : compatibilité mécanique avec la caméra.</li><li><b>T-stop</b> : ouverture mesurée en lumière réellement transmise, utile pour égaliser un jeu d’objectifs.</li><li><b>Anamorphique :</b> compresse l’image horizontalement (à désétirer), flares horizontaux et bokeh ovale.</li><li><b>Filtre ND :</b> ND 0,3 = 1 stop, ND 0,6 = 2 stops, ND 0,9 = 3 stops.</li></ul><div class="note"><b>À retenir :</b> grande ouverture + grand capteur + longue focale = faible profondeur de champ.</div>`),
les("📖 2. Signal, échantillonnage et débit",`<h3>Résolution et cadence</h3><p>Full HD 1920×1080, UHD 3840×2160 (grand public), 4K DCI 4096×2160 (cinéma). Cadences : 24 i/s (cinéma), 25 i/s (TV Europe), 29,97 i/s (NTSC, en réalité 30000/1001), 50 i/s et 59,94 i/s pour la fluidité. Progressif (p) : image complète ; entrelacé (i) : deux demi-images (trames) par image, ex. 1080i50.</p><h3>Sous-échantillonnage de la chrominance</h3><p>L’œil est moins sensible à la couleur qu’à la luminance. On garde toute la luminance (Y) et on réduit la chrominance (Cb, Cr).</p><ul><li><b>4:4:4</b> : pleine résolution couleur.</li><li><b>4:2:2</b> : couleur divisée par 2 horizontalement (standard broadcast et montage).</li><li><b>4:2:0</b> : divisée par 2 en horizontal et vertical (diffusion, H.264 grand public).</li></ul><h3>Profondeur de bits</h3><p>8 bits = 256 niveaux par composante, 10 bits = 1 024, 12 bits = 4 096. Plus de bits = dégradés plus doux, étalonnage plus souple.</p><h3>Calculer un débit non compressé</h3><p>Débit = largeur × hauteur × images/s × bits par pixel.<br>Exemple 1080p25, 4:2:2, 10 bits (20 bits par pixel en moyenne) : 1920 × 1080 × 25 × 20 ≈ <b>1,04 Gb/s</b>.</p><div class="note"><b>Conversion :</b> 8 bits = 1 octet. 80 Mb/s = 10 Mo/s. Un flux de 100 Mb/s pendant 1 h : 100 × 3 600 ÷ 8 = 45 000 Mo ≈ <b>45 Go</b>.</div>`),
les("📖 3. Codecs, conteneurs et formats",`<h3>Codec ≠ conteneur</h3><p>Le <b>codec</b> compresse/décompresse l’image ou le son. Le <b>conteneur</b> est l’enveloppe qui regroupe vidéo, audio, timecode et métadonnées (MOV, MP4, MXF, MKV).</p><h3>Compression intra et inter</h3><ul><li><b>Intra-frame :</b> chaque image est codée seule (ProRes, DNxHR, XAVC Intra). Lourd en débit mais fluide au montage.</li><li><b>Inter-frame (GOP) :</b> images I (complètes), P (prédites), B (bidirectionnelles). H.264, H.265 : très légers, mais le décodage coûte du processeur.</li></ul><h3>Familles à connaître</h3><ul><li><b>Apple ProRes :</b> Proxy, LT, 422, 422 HQ, 4444 (avec canal alpha possible), 4444 XQ.</li><li><b>Avid DNxHD / DNxHR :</b> LB, SQ, HQ, HQX, 444.</li><li><b>MXF :</b> conteneur broadcast, utilisé nativement par Avid (OP-Atom).</li></ul><h3>Les 4 usages d’un codec</h3><ol><li><b>Tournage</b> (capture) : RAW, XAVC, ProRes RAW.</li><li><b>Montage</b> : ProRes, DNxHR (ou proxys).</li><li><b>Diffusion</b> : H.264, H.265.</li><li><b>Archivage</b> : fichiers mezzanine de haute qualité.</li></ol><div class="note">Transcoder en codec de montage ou créer des <b>proxys</b> permet de monter fluide sur des machines modestes, puis de reconnecter les originaux (conformation).</div>`),
les("📖 4. Stockage, sauvegarde et connectique",`<h3>Les supports</h3><ul><li><b>HDD</b> : capacité élevée, ~150 Mo/s, fragile.</li><li><b>SSD SATA</b> : ~500 Mo/s. <b>SSD NVMe</b> : plusieurs Go/s.</li></ul><h3>Interfaces</h3><ul><li>USB 3.x : 5 à 20 Gb/s selon la version.</li><li>Thunderbolt 3/4 : 40 Gb/s.</li><li>Ethernet 1 GbE / 10 GbE pour NAS et stockage partagé.</li></ul><h3>Liaisons vidéo</h3><ul><li><b>SDI</b> (connecteur BNC) : SD 270 Mb/s, HD 1,485 Gb/s, 3G 2,97 Gb/s, 6G, 12G. Câble long, verrouillable.</li><li><b>HDMI</b> : grand public, câble court, pas de verrouillage.</li></ul><h3>RAID</h3><ul><li><b>RAID 0</b> : répartition (vitesse), aucune sécurité.</li><li><b>RAID 1</b> : miroir (sécurité), capacité divisée par 2.</li><li><b>RAID 5</b> : parité, ≥ 3 disques, survit à 1 panne. <b>RAID 6</b> : 2 pannes.</li></ul><h3>Bonnes pratiques</h3><ol><li>Décharger les cartes avec <b>vérification checksum</b> (MD5, xxHash).</li><li>Appliquer la règle <b>3-2-1</b>.</li><li>Un RAID n’est pas une sauvegarde : il protège d’une panne de disque, pas d’une erreur humaine.</li></ol>`),
les("📖 5. Audio numérique",`<h3>Numériser le son</h3><p>L’<b>échantillonnage</b> mesure le signal à intervalles réguliers. D’après Nyquist, la fréquence maximale reproductible est la moitié de la fréquence d’échantillonnage : à 48 kHz, 24 kHz. La <b>quantification</b> (16 ou 24 bits) donne la précision : environ 6 dB de dynamique par bit, soit ≈ 96 dB en 16 bits et ≈ 144 dB en 24 bits.</p><h3>Niveaux</h3><ul><li><b>dBFS</b> : 0 dBFS est le maximum numérique ; on ne le dépasse jamais (clipping, distorsion irrécupérable).</li><li>Niveau de ligne (pro +4 dBu) beaucoup plus fort que niveau micro : préampli nécessaire.</li></ul><h3>Loudness</h3><p>Norme <b>EBU R128</b> (Europe) : −23 LUFS (±0,5 LU) et crête réelle maximale −1 dBTP. Les plateformes web visent souvent autour de −14 à −16 LUFS (à vérifier selon la plateforme).</p><h3>Micros et câbles</h3><ul><li><b>Dynamique</b> : robuste. <b>Statique</b> (à condensateur) : plus sensible, alimentation fantôme 48 V.</li><li>Directivités : omnidirectionnel, cardioïde, hypercardioïde (canon).</li><li>Liaison <b>XLR symétrique</b> : rejette les parasites sur longue distance.</li></ul>`),
les("📖 6. Timecode, synchronisation et colorimétrie",`<h3>Timecode</h3><p>Il numérote chaque image : HH:MM:SS:FF. À 25 i/s, pas de problème. À 29,97 i/s, le timecode compte 30 images par seconde et dérive : le <b>drop frame</b> saute les numéros 00 et 01 au début de chaque minute, sauf les minutes multiples de 10 (aucune image n’est supprimée, seulement des numéros).</p><ul><li><b>LTC</b> : timecode sur une piste audio. <b>Genlock</b> : synchronise le balayage des appareils (black burst, tri-level).</li></ul><h3>Espaces colorimétriques</h3><ul><li><b>Rec.709</b> : HD/SDR. <b>Rec.2020</b> : UHD, gamut étendu. <b>DCI-P3</b> : cinéma numérique. <b>sRGB</b> : web.</li><li>HDR : courbes <b>PQ</b> (ST 2084) et <b>HLG</b>, en 10 bits minimum.</li><li>Niveaux vidéo (limited 16–235 en 8 bits) vs niveaux data (full 0–255) : une confusion donne une image délavée ou écrasée.</li></ul><h3>Scopes</h3><ul><li><b>Waveform</b> : luminance. <b>Parade RVB</b> : équilibre des couches. <b>Vectorscope</b> : teinte et saturation (la ligne de peau).</li></ul>`)
];

/* ============ Image fixe ============ */
COURS.img.push(
["Exposition en détail",["1 stop = ×2 ou ÷2 de lumière : f/5,6 → f/11 = 2 stops = 4 fois moins de lumière.","Règle du flou de bougé : vitesse ≥ 1/focale (50 mm → 1/50 s).","Mesure matricielle, pondérée centrale ou spot ; gris moyen = 18 %."]],
["Optique & perspective",["Grand angle < 35 mm, normal ≈ 50 mm, télé > 85 mm (plein format).","La perspective dépend de la distance au sujet, pas de la focale.","Profondeur de champ : ouverture, focale, distance, taille du capteur."]],
["Lumière",["Dure (ombres nettes, source petite) / douce (source large ou diffusée).","Température : bougie ≈ 1 900 K, tungstène 3 200 K, jour 5 600 K, ciel couvert ≈ 6 500 K+.","Trois points : principale (key), appoint (fill), contre-jour (rim/back)."]],
["Fichiers & couleur",["JPEG (8 bits, avec perte), PNG (sans perte, transparence), TIFF, RAW (12–14 bits), PSD.","Impression : 300 ppp. Pouces = pixels ÷ ppp (1 pouce = 2,54 cm).","Profils ICC : sRGB (web), Adobe RGB (gamut plus large), ProPhoto RGB."]]
);
LESSONS.img=[
les("📖 1. Le triangle d’exposition",`<h3>Les trois réglages</h3><ul><li><b>Ouverture (f/)</b> : f/1,4 – 2 – 2,8 – 4 – 5,6 – 8 – 11 – 16 – 22. Chaque cran divise la lumière par 2 et augmente la profondeur de champ.</li><li><b>Vitesse</b> : 1/30, 1/60, 1/125, 1/250… Chaque cran divise le temps d’exposition par 2 et fige mieux le mouvement.</li><li><b>ISO</b> : 100 – 200 – 400 – 800… Chaque cran double la sensibilité mais augmente le bruit.</li></ul><h3>Équivalences</h3><p>Une même exposition peut être obtenue par plusieurs combinaisons : 1/125 s à f/4 équivaut à 1/250 s à f/2,8 (on gagne 1 stop de vitesse, on en rend 1 d’ouverture). Le choix dépend de l’intention : profondeur de champ, mouvement, bruit.</p><h3>Mesurer la lumière</h3><ul><li><b>Matricielle</b> : analyse toute la scène. <b>Pondérée centrale</b> : privilégie le centre. <b>Spot</b> : une petite zone.</li><li>Le posemètre vise le <b>gris moyen (18 %)</b> : une scène très claire sera sous-exposée, une scène sombre sur-exposée, d’où la <b>compensation d’exposition</b> (±IL).</li><li><b>Histogramme</b> : à gauche les ombres, à droite les hautes lumières. Un histogramme collé à droite signale un risque de surexposition.</li></ul><div class="note"><b>Astuce :</b> en RAW, il vaut mieux légèrement sous-exposer que brûler les hautes lumières, car on récupère mieux les ombres.</div>`),
les("📖 2. Optique, focale et profondeur de champ",`<h3>Les focales (plein format)</h3><ul><li><b>Grand angle</b> (14–35 mm) : champ large, perspective accentuée.</li><li><b>Normal</b> (≈ 50 mm) : proche du regard.</li><li><b>Télé</b> (85 mm et plus) : champ étroit, plans compressés.</li></ul><p>Attention : la perspective vient de la <b>distance au sujet</b>. Un téléobjectif « écrase » parce qu’on se place plus loin, pas par magie de la focale.</p><h3>Profondeur de champ (PDC)</h3><p>C’est la zone nette devant et derrière le point de mise au point. Elle augmente quand on <b>ferme</b> le diaphragme, qu’on <b>raccourcit</b> la focale, qu’on <b>s’éloigne</b>, ou qu’on utilise un <b>petit capteur</b>.</p><ul><li><b>Hyperfocale</b> : distance de mise au point qui rend net de la moitié de cette distance jusqu’à l’infini (paysage).</li><li><b>Bokeh</b> : qualité esthétique du flou d’arrière-plan.</li></ul><h3>Défauts optiques</h3><ul><li>Distorsion (barillet, coussinet), vignettage, aberrations chromatiques, diffraction aux très petites ouvertures (f/22).</li></ul>`),
les("📖 3. La lumière et la couleur",`<h3>Qualité de lumière</h3><ul><li><b>Dure</b> : source petite ou éloignée, ombres marquées (soleil de midi, projecteur nu).</li><li><b>Douce</b> : source large ou diffusée (ciel couvert, boîte à lumière), ombres douces.</li></ul><h3>Direction</h3><p>Face (aplatit), 3/4 (modèle le volume, la plus classique en portrait), latérale (texture), contre-jour (silhouette, halo), plongée / contre-plongée (selon la hauteur de la source).</p><h3>Éclairage trois points</h3><ol><li><b>Key</b> : lumière principale.</li><li><b>Fill</b> : débouche les ombres ; le ratio key:fill de 4:1 correspond à 2 stops d’écart.</li><li><b>Back / rim</b> : détache le sujet du fond.</li></ol><h3>Température de couleur</h3><p>Exprimée en kelvins : bougie ≈ 1 900 K, tungstène ≈ 3 200 K, lumière du jour ≈ 5 600 K, ciel couvert ≈ 6 500 K et plus. Plus la valeur est basse, plus la lumière est chaude (orangée). La <b>balance des blancs</b> règle l’appareil pour que le blanc reste neutre.</p><ul><li><b>Gel CTO</b> : réchauffe (jour → tungstène). <b>CTB</b> : refroidit.</li><li><b>IRC / CRI</b> : fidélité de rendu des couleurs d’une source (100 = idéal).</li></ul><h3>Cercle chromatique</h3><p>Couleurs complémentaires (rouge/vert, bleu/orange) = contraste fort ; analogues = harmonie douce.</p>`),
les("📖 4. Composition de l’image",`<h3>Les outils de composition</h3><ul><li><b>Règle des tiers</b> : placer les éléments forts sur les lignes ou intersections d’une grille 3×3.</li><li><b>Lignes de fuite</b> et <b>lignes de force</b> : guident le regard.</li><li><b>Symétrie</b>, <b>équilibre</b> des masses, <b>vide</b> (espace négatif).</li><li><b>Plans</b> : premier plan, plan principal, arrière-plan pour créer de la profondeur.</li><li><b>Cadrage dans le cadre</b> (porte, fenêtre), contraste d’échelle ou de couleur.</li></ul><h3>Choisir son point de vue</h3><p>Hauteur de prise de vue, distance, cadrage vertical ou horizontal : chaque choix change le sens. Un sujet photographié en contre-plongée est valorisé, en plongée il est rapetissé.</p><h3>Lire une image</h3><ol><li>Décrire (sujet, cadrage, lumière, couleurs).</li><li>Analyser (composition, choix techniques).</li><li>Interpréter (intention, message, émotion).</li></ol>`),
les("📖 5. Fichiers, résolution et gestion de la couleur",`<h3>Pixel, résolution, ppp</h3><p>Une image 6000 × 4000 px = 24 mégapixels. La résolution d’impression se donne en <b>ppp (dpi)</b> : pour imprimer à 300 ppp, 3 000 px donnent 10 pouces soit 25,4 cm ; 6 000 px donnent 20 pouces ≈ 51 cm. À l’écran, seuls les pixels comptent.</p><h3>Formats de fichiers</h3><ul><li><b>JPEG</b> : avec perte, 8 bits, léger.</li><li><b>PNG</b> : sans perte, transparence.</li><li><b>TIFF</b> : sans perte, impression, 16 bits possible.</li><li><b>RAW</b> : données brutes du capteur, 12–14 bits, à développer.</li><li><b>PSD</b> : fichier Photoshop avec calques.</li><li><b>SVG</b> : vectoriel (formes mathématiques, indépendant de la résolution) vs images <b>matricielles</b> (pixels).</li></ul><h3>Modes colorimétriques</h3><ul><li><b>RVB</b> : synthèse additive (lumière) pour les écrans.</li><li><b>CMJN</b> : synthèse soustractive (encres) pour l’impression.</li><li>Niveaux de gris, Lab, couleurs indexées.</li></ul><h3>Profils ICC</h3><p>Un profil décrit comment interpréter les couleurs d’un espace ou d’un appareil. <b>sRGB</b> (web), <b>Adobe RGB</b> (gamut plus large), <b>ProPhoto</b> (très large). Toujours convertir au profil de destination en fin de chaîne.</p>`),
les("📖 6. Histoire de l’art : Mémoires (préhistoire et Égypte)",`<h3>L’art préhistorique : naissance des images</h3><p>La préhistoire précède l’invention de l’écriture (vers -3500). L’homme pensant apparaît il y a environ 300 000 ans. On étudie ici l’<b>art pariétal</b> (sur les parois des grottes), dont <b>Lascaux</b> (Dordogne, vers -18 000) est l’exemple le plus connu. Sans témoignage écrit, toute interprétation reste une <b>hypothèse</b>.</p><h3>Pourquoi créer des images ?</h3><ul><li><b>Religieuse</b> : faire advenir les puissances divines que sont les animaux.</li><li><b>Symbolique</b> : clans, principe masculin et féminin, temps.</li><li><b>Sociale</b> : lieux magiques pour des rites de passage (initiation).</li><li><b>Narrative</b> : raconter ce qui a eu lieu.</li></ul><p>On ne pense plus qu’elles aient eu une fonction décorative : l’image n’est pas une simple représentation, elle <b>fait advenir</b>. Elle s’inscrit dans un <b>art total</b> (musique, danse, costumes, lumière, récits).</p><ul><li><b>Magie de la chasse</b> : représenter l’animal pour assurer la chasse, ou l’apaiser (offrande, hommage).</li><li><b>Grands récits mythologiques</b> : mythes révélés lors de cérémonies, à la lueur de la flamme.</li></ul><h3>Comment et lien avec l’audiovisuel</h3><ul><li>Animaux représentés de façon réaliste ; les reliefs de la paroi donnent du volume ; pigments naturels (charbon, terres).</li><li>La grotte est sombre et les images semblent <b>mouvantes à la flamme</b> : un lieu et une lumière comme au cinéma.</li><li>L’image procède par <b>fragments, superpositions, associations</b> : comment une accumulation d’images produit-elle du sens (question de montage) ?</li></ul><h3>La mémoire des images</h3><p>Des grottes fréquentées sur plusieurs générations : la paroi est un <b>espace de mémoire collective</b>. Cinéma et photographie enregistrent des traces du réel, mais une image résulte de choix (cadrage, sélection, point de vue, montage) : <b>toute mémoire est une construction</b>.</p><div class="note"><b>Pistes :</b> créer une image, est-ce déjà lutter contre l’oubli ? Références : Arte <i>Artjacking</i> et <i>Quand l’histoire fait date : Lascaux</i> ; Altamira (Espagne) ; Grotte des mains (Patagonie, vers -13 000) ; Yves Klein, <i>Hiroshima</i>.</div><h3>L’Égypte antique : un art funéraire</h3><p>Grandes dynasties, environ 3 000 ans av. J.-C. L’art assure la <b>survie du défunt</b> : l’œuvre n’est pas faite pour être regardée, elle est <b>magique</b> et fait être. Le corps est préservé (embaumement, momies) pour que l’âme survive ; les fresques des tombeaux montrent la vie du défunt, les dieux (Horus, Anubis) : tout ce qui est peint existera dans l’au-delà. Être représenté, c’est continuer à exister dans la mémoire des vivants.</p><h3>Une représentation codifiée</h3><ul><li><b>Aspectivité</b> : chaque partie du corps sous son aspect le plus identifiable (tête et jambes de profil, œil et torse de face).</li><li>Pas de profondeur, <b>hiérarchie des tailles</b>, étagement, mélange texte et image.</li><li>Pas de volume : <b>aplat</b> sans modelé ni dégradé ; symbolique des couleurs.</li><li>Image <b>claire, lisible et durable</b>.</li></ul><p>Les <b>hiéroglyphes</b> lient écriture et image : aujourd’hui encore, génériques, réseaux sociaux, affiches ou interfaces associent texte et image.</p><h3>Conclusion : laisser et préserver la trace</h3><p>L’œuvre survit à son créateur mais la transmission est lacunaire : <b>la mémoire est aussi une reconstruction du passé depuis le présent</b>. Notre époque produit une immense mémoire visuelle mais fragile, alors que des peintures de grottes ont traversé des dizaines de milliers d’années. Qui conserve les traces ? De nombreuses œuvres égyptiennes ont été pillées ; la question de la <b>restitution</b> au pays d’origine se pose.</p><div class="note"><b>Notions :</b> art pariétal, art total, art funéraire, aspectivité, aplat, mémoire collective.</div>`),
les("📖 7. Histoire de l’art : Mémoires (Grèce et Moyen Âge)",`<h3>L’Antiquité grecque : qui et quand</h3><p>La Grèce est un ensemble de <b>cités indépendantes</b> (Athènes, Sparte, Corinthe…) sur tout le bassin méditerranéen. Les artistes sont longtemps anonymes (Phidias, Polyclète, Praxitèle sont des exceptions) ; la notion d’artiste apparaît à la Renaissance. Époques : <b>archaïque</b> (VIIIe – début Ve s. av. J.-C.), <b>classique</b> (Ve – IVe s.), <b>hellénistique</b> (323 – 31 av. J.-C.). Mouvement général : d’une représentation schématique et codifiée vers un art de plus en plus naturaliste, dynamique et expressif.</p><h3>Les récits et l’héritage</h3><ul><li>Homère (<i>Iliade</i>, <i>Odyssée</i>), Hésiode (<i>Théogonie</i>), tragiques (Eschyle, Sophocle, Euripide) ; Ovide (romain, <i>Métamorphoses</i>, début de notre ère) transmet les mythes à l’Occident.</li><li>Architecture classique et néoclassique (Parthénon, Grand Théâtre et quais de Bordeaux, fontaine des Trois Grâces).</li><li>Statuaire modèle de réalisme, de beauté idéale et d’expressivité ; expressions (talon d’Achille, boîte de Pandore, cheval de Troie), vocabulaire politique, Jeux olympiques.</li></ul><h3>Le corps idéal</h3><ul><li><b>Archaïque</b> : <b>kouroi</b> nus, frontaux, rigides, selon un <b>canon</b>. Idéal viril : <b>kalos kagathos</b> (« beau et bon »). <b>Korai</b> : pieds joints, rarement nues. Exemples : Cléobis et Biton (Delphes, vers -580), Dame d’Auxerre.</li><li><b>Classique</b> : naturel et mouvement, <b>contrapposto</b> (Discobole).</li><li><b>Hellénistique</b> : émotion, réalisme à son apogée (Laocoon).</li></ul><h3>Pourquoi et lien avec la mémoire</h3><p>Fonctions religieuse, politique, funéraire, commémorative, esthétique : l’art construit l’<b>identité collective</b> (le Parthénon affirme la puissance d’Athènes). Contrairement à l’art préhistorique ou égyptien, la statue n’est pas magique, mais elle rend le dieu <b>présent et visible</b>. Statues funéraires, monuments et mythes fixés dans la pierre forment une <b>mémoire matérielle</b>. On ne représente pas ce qui existe mais ce dont une société veut se souvenir : la mémoire est une sélection, donc une création.</p><h3>La période médiévale</h3><p>Ve – XVe siècle, Europe chrétienne : l’Église (avec monastères, rois, princes) commande et conserve les œuvres. L’image est un <b>instrument religieux</b> qui transmet les récits bibliques. Haut Moyen Âge (Ve – Xe), <b>roman</b> (XIe – XIIe : massif, peu de lumière) et <b>gothique</b> (XIIe – XVe : verticalité, vitraux).</p><h3>Icônes et enluminures</h3><ul><li><b>Icônes orthodoxes</b> (dès le VIe s.) : images symboliques, présence spirituelle ; frontalité, symétrie, fixité, fonds dorés, pas de profondeur. Querelle <b>iconoclastes / iconodoules</b> (VIIIe – IXe s.).</li><li><b>Enluminures</b> : personnages stylisés en aplat, lettres ornées ; image simplifiée, échelles peu réalistes, gestuelle théâtrale, pour être compréhensible et mémorisable.</li><li><b>Gothique</b> : arc brisé, voûte sur croisée d’ogives, arc-boutant ; la lumière devient un élément théologique.</li></ul><h3>Fonctions et mémoire</h3><p>Transmettre la foi à une population largement illettrée (récit visuel : Bible, saints, Passion, Jugement dernier) et affirmer le pouvoir des rois. Cathédrales et vitraux conservent les récits chrétiens ; manuscrits enluminés, tombeaux (basilique de Saint-Denis) et tapisserie de Bayeux (conquête de 1066) font de l’art une mémoire politique et historique.</p><div class="note"><b>Notions :</b> canon, contrapposto, idéalisation, iconographie, art roman, art gothique, enluminure, programme iconographique, mémoire collective.</div><h3>Conclusion : l’art, fabrique de la mémoire</h3><p>Cathédrale, tombeau, manuscrit, tapisserie conservent et transmettent, mais cette mémoire est toujours <b>construite</b> : une société choisit ce qu’elle représente et transmet. Question centrale : <b>« Comment les œuvres d’art transforment-elles le passé en mémoire collective ? »</b></p>`)
];

